def compare_publication_inventory(directory, namespaces):
    baseline_manifest = baseline_files = None
    for lane in roots:
        for repeat in ('a', 'b'):
            root = lane / (directory + '-' + repeat)
            raw = (root / 'manifest.json').read_bytes()
            matrix = json.loads(raw)
            names = [item['file'] for item in matrix['candidates'] + matrix['cases']]
            assert names and len(names) == len(set(names)), (root, names)
            for name in names:
                path = PurePosixPath(name)
                assert not path.is_absolute() and '..' not in path.parts, (root, name)
                assert path.as_posix() == name and path.parts[0] in namespaces, (root, name)
            inventory = set()
            for namespace in namespaces:
                folder = root / namespace
                assert folder.is_dir() and not folder.is_symlink(), folder
                for path in folder.rglob('*'):
                    assert not path.is_symlink(), path
                    if path.is_file():
                        inventory.add(path.relative_to(root).as_posix())
            assert inventory == set(names), (root, inventory ^ set(names))
            files = {name: (root / name).read_bytes() for name in names}
            if baseline_manifest is None:
                baseline_manifest, baseline_files = raw, files
            else:
                assert raw == baseline_manifest, root
                assert files == baseline_files, root
    assert (a / (directory + '-a/evidence.json')).read_bytes() == \
           (b / (directory + '-a/evidence.json')).read_bytes(), directory
    return json.loads(baseline_manifest), json.loads(
        (a / (directory + '-a/evidence.json')).read_text())

