/** One analyzer-owned pair of a Boolean AST and its integer 0/1 encoding.
  * The existing integer ingress remains the only source of exact authority;
  * this wrapper only authorizes retaining the original predicate rendering
  * after that ingress and its native equality have passed validation.
  */
final class AnalyzedFrontendBoolean private[frontend] (
    private val source: HdlBool,
    private val expression: ElaborationBooleanExpression,
    private val encodedSource: HdlInt,
    private val encodedAnalysis: AnalyzedFrontendInteger,
    private val analyzerSeal: AnyRef
) {
  private[this] var consumed = false

  def claim(): (
      ElaborationBooleanExpression,
      AnalyzedFrontendInteger
  ) = synchronized {
    if (!StructuralExpressionBridge.authenticatesFrontendBoolean(analyzerSeal)) {
      FrontendException.failAt(
        "MORPH-FRONTEND-ANALYZED-BOOLEAN-AUTHORIZATION-INVALID",
        "analyzed Boolean wrapper was not constructed by the frontend AST analyzer",
        SourceOrigin("<analyzed-Boolean>", 1)
      )
    }
    if (consumed) {
      FrontendException.failAt(
        "MORPH-FRONTEND-ANALYZED-BOOLEAN-AUTHORIZATION-CONSUMED",
        "analyzed Boolean wrapper already published its exact predicate",
        source.origin
      )
    }
    encodedAnalysis.requireAnalyzerAuthentication()
    val integer = encodedAnalysis.expression
    val sameEncoding = encodedSource.expression match {
      case IntExpr.Select(condition, IntExpr.Literal(one), IntExpr.Literal(zero)) =>
        (condition eq source.expression) && one == 1 && zero == 0
      case _ => false
    }
    if (
      !(encodedAnalysis.sourceIdentity eq encodedSource) || !sameEncoding ||
      expression.default != source.witness ||
      integer.default != (if (expression.default) BigInt(1) else BigInt(0)) ||
      expression.parameters.size != integer.parameters.size ||
      !expression.parameters.zip(integer.parameters).forall { case (left, right) =>
        left eq right
      } ||
      expression.parameterRoots.size != integer.parameterRoots.size ||
      !expression.parameterRoots.zip(integer.parameterRoots).forall { case (left, right) =>
        left eq right
      } ||
      expression.sourceLocation != integer.sourceLocation
    ) {
      FrontendException.failAt(
        "MORPH-FRONTEND-ANALYZED-BOOLEAN-SOURCE-MISMATCH",
        "analyzed Boolean predicate and its integer encoding do not retain the same exact source",
        source.origin
      )
    }
    consumed = true
    (expression, encodedAnalysis)

  )
}

/** Both renderings are derived here from the same exact predicate AST.
  * The integer product deliberately follows the unchanged HdlInt.asElabInt
  * analysis path, including its unsupported-case diagnostics.
  */
def analyzedBoolean(
    value: HdlBool,
    role: String
): AnalyzedFrontendBoolean = {
  if (value eq null) {
    FrontendException.fail(
      "MORPH-FRONTEND-STRUCTURAL-BOOLEAN-NULL",
      s"$role requires a non-null HdlBool"
    )
  }
  val encoded = HdlInt.select(
    value,
    HdlInt.literalAt(BigInt(1), value.origin),
    HdlInt.literalAt(BigInt(0), value.origin),
    value.origin
  )
  val integer = analyzedWidth(encoded, "typed elaboration integer")
  new AnalyzedFrontendBoolean(
    source = value,
    expression = booleanImpl(value, role, allowPortableLogHelper = true),
    encodedSource = encoded,
    encodedAnalysis = integer,
    analyzerSeal = FrontendBooleanAnalyzerSeal

): ElaborationBooleanExpression =
  booleanImpl(value, role, allowPortableLogHelper = false)

private def booleanImpl(
    value: HdlBool,
    role: String,
    allowPortableLogHelper: Boolean

/** Canonical construction normalization, independent of optional RTL passes.
  * The opaque pair proves that the direct predicate and the integer select
  * came from the same AST. Preserve the established ingress checks before
  * transferring its exact Boolean result metadata to that direct rendering.
  */
def boolean(analyzed: AnalyzedFrontendBoolean): ElabBool = {
  if (analyzed == null)
    throw new IllegalArgumentException("analyzed Boolean wrapper must not be null")
  val (predicate, encoded) = analyzed.claim()
  val integer = encoded.singleRootEvaluations match {
    case Some(evaluations) =>
      ElabInt.fromSingleRootExpression(
        encoded.expression,
        evaluations,
        singleRoot(encoded)
      )
    case None => ElabInt.fromExpression(encoded.expression)
  }
  val validated = integer.elabEq(1)
  ElabBool.derived(
    validated.expression.copy(verilog = predicate.verilog),
    validated.truth,
    "analyzed frontend Boolean normalization"
  )
}

package morphhdl.frontend

import org.scalatest.funsuite.AnyFunSuite

import spinal.core.{ExternalAnalyzedFrontendPermitIssuer, ParameterizedVerilogException}

class AnalyzedFrontendBooleanTests extends AnyFunSuite {
  test("native ingress keeps direct parameter compound and negated predicates") {
    val enabled = HdlBool.param("ENABLE", default = false).asElabBool
    assert(enabled.toString.contains("ENABLE == 1"))
    assert(!enabled.toString.contains("?"))

    val width = HdlInt.param("WIDTH", default = 4, min = 1, max = 8)
    val compound = ((width > 2) && !width.hdlEq(5)).asElabBool
    assert(compound.isSymbolic)
    assert(compound.toString.contains("&&"))
    assert(compound.toString.contains("!"))
    assert(!compound.toString.contains("?"))
    assert(compound.parameters.map(_.name) == Vector("WIDTH"))
  }

  test("direct Boolean analysis authorizes exactly one native publication") {
    val source = HdlBool.param("ENABLE", default = false)
    val analyzed = StructuralExpressionBridge.analyzedBoolean(source, "test predicate")
    val value = ExternalAnalyzedFrontendPermitIssuer.boolean(analyzed)
    assert(value.isSymbolic)
    assert(value.parameters.map(_.name) == Vector("ENABLE"))

    val replay = intercept[FrontendException] {
      ExternalAnalyzedFrontendPermitIssuer.boolean(analyzed)
    }
    assert(replay.code == "MORPH-FRONTEND-ANALYZED-BOOLEAN-AUTHORIZATION-CONSUMED")
  }

  test("a copied predicate and valid integer analysis cannot forge Boolean authority") {
    val source = HdlBool.param("ENABLE", default = false)
    val encoded = HdlInt.select(
      source,
      HdlInt.literalAt(BigInt(1), source.origin),
      HdlInt.literalAt(BigInt(0), source.origin),
      source.origin
    )
    val integer = StructuralExpressionBridge.analyzedWidth(encoded, "test integer")
    val predicate = StructuralExpressionBridge.boolean(source, "test predicate")
    val forged = new AnalyzedFrontendBoolean(
      source,
      predicate.copy(verilog = "FOREIGN_PARAMETER"),
      encoded,
      integer,
      new Object
    )
    val error = intercept[FrontendException] {
      ExternalAnalyzedFrontendPermitIssuer.boolean(forged)
    }
    assert(error.code == "MORPH-FRONTEND-ANALYZED-BOOLEAN-AUTHORIZATION-INVALID")

    // A forged Boolean publication must not consume the independent valid
    // integer analyzer permit before its own authentication fails.
    ExternalAnalyzedFrontendPermitIssuer.singleRoot(integer)
  }

  test("direct predicates preserve portable width-helper support") {
    val depth = HdlInt.param("DEPTH", default = 4, min = 1, max = 8)
    val ceiling = (depth.ceilLog2 > 1).asElabBool
    val address = (depth.addressWidth > 1).asElabBool
    Vector(ceiling, address).foreach { predicate =>
      assert(predicate.isSymbolic)
      assert(predicate.toString.contains("clog2(DEPTH,"))
      assert(!predicate.toString.contains("?"))
      assert(predicate.parameters.map(_.name) == Vector("DEPTH"))
    }
  }

  test("native Boolean normalization retains unsupported local diagnostics") {
    val enabled = HdlBool.param("ENABLE", default = false)
    val local = ParamRtlFrontend.localParam("LOCAL_ENABLE", enabled)
    val error = intercept[FrontendException] {
      local.asElabBool
    }
    assert(error.code == "MORPH-FRONTEND-STRUCTURAL-LOCAL-PARAMETER-UNSUPPORTED")
  }

  test("native Boolean normalization retains independent-root diagnostics") {
    val enabled = HdlBool.param("ENABLE", default = false)
    val bypass = HdlBool.param("BYPASS", default = true)
    val error = intercept[ParameterizedVerilogException] {
      (enabled || bypass).asElabBool
    }
    assert(error.code == "SPINAL-ELAB-DOMAIN-EVIDENCE-MISSING")
  }
}

package morphhdl.frontend

import org.scalatest.funsuite.AnyFunSuite
import spinal.core.{ElabInt, ParameterizedVerilogException}

class TypedParameterFrontendTests extends AnyFunSuite {
  test("direct typed parameter import preserves the exact schema and declaration root") {
    val native = HdlInt.param("MODE", 1, 1, 2).asElabInt
    val original = native.bits.expression.get
    val imported = HdlInt.fromElabIntParameter(native)
    val retained = imported.asElabInt.bits.expression.get

    assert(imported.expression == morphhdl.paramrtl.IntExpr.ParameterRef("MODE"))
    assert(retained.parameters.head eq original.parameters.head)
    assert(retained.parameterRoots.head eq original.parameterRoots.head)
    assert(retained.default == 1)
    assert(retained.minimum == 1)
    assert(retained.maximum == 2)
  }

  test("typed control parameter import preserves both values of its logical encoding") {
    for (default <- 1 to 2) {
      val native = HdlInt.param("MODE", default, 1, 2).asElabInt
      val imported = HdlInt.fromElabIntParameter(native) - HdlInt.literal(1)
      val analyzed = StructuralExpressionBridge.analyzedWidth(imported, "logical MODE")

      assert(analyzed.expression.default == default - 1)
      assert(analyzed.expression.minimum == 0)
      assert(analyzed.expression.maximum == 1)
      assert(analyzed.singleRootEvaluations.contains(
        Vector(BigInt(1) -> BigInt(0), BigInt(2) -> BigInt(1))))
      assert(analyzed.expression.parameterRoots.head eq native.bits.expression.get.parameterRoots.head)
    }
  }

  test("repeated imports retain one native declaration identity") {
    val native = HdlInt.param("COUNT", 3, 1, 17).asElabInt
    val first = HdlInt.fromElabIntParameter(native).asElabInt.bits.expression.get
    val second = HdlInt.fromElabIntParameter(native).asElabInt.bits.expression.get
    assert(first.parameters.head eq second.parameters.head)
    assert(first.parameterRoots.head eq second.parameterRoots.head)
  }

  test("typed parameter import rejects arithmetic even when its value is unchanged") {
    val native = HdlInt.param("MODE", 1, 1, 2).asElabInt
    val failure = intercept[FrontendException] {
      HdlInt.fromElabIntParameter(native + 0)
    }
    assert(failure.code == "MORPH-FRONTEND-TYPED-PARAMETER-NOT-DIRECT")
  }

  test("typed parameter import rejects literals and null") {
    val literal = intercept[FrontendException] {
      HdlInt.fromElabIntParameter(ElabInt.literal(1))
    }
    assert(literal.code == "MORPH-FRONTEND-TYPED-PARAMETER-NOT-DIRECT")
    val absent = intercept[FrontendException] {
      HdlInt.fromElabIntParameter(null)
    }
    assert(absent.code == "MORPH-FRONTEND-TYPED-PARAMETER-NULL")
  }

  test("typed parameter import cannot certify copied descriptive metadata") {
    val native = HdlInt.param("MODE", 1, 1, 2).asElabInt
    val source = native.bits.expression.get
    val failure = intercept[ParameterizedVerilogException] {
      HdlInt.fromElabIntParameter(ElabInt.fromExpression(source.copy()))
    }
    assert(failure.code == "SPINAL-ELAB-DOMAIN-EXACT-AUTHORITY-MISSING", failure.getMessage)
  }
}

