        val values = in(Vec(BalancedConsumedProbeRecord(depth), HdlInt.param("COUNT", 1, 1, 3)))
        val reduced = values.reduceBalancedTree((a: BalancedConsumedProbeRecord, b: BalancedConsumedProbeRecord) => {
          val result = cloneOf(a)
          result.flag := a.flag | b.flag
          result.payload := a.payload
          result
        })
        val probes = ParameterizedVec.retainedVectorsOf(this).filter(TypedBalancedReductionBackend.ownsConsumedProbe)
        assert(probes.nonEmpty, "certified native callbacks produced no consumed Vec receipt")
        val probe = probes.head.asInstanceOf[Vec[Bits]]
        assert(probe.asInstanceOf[Data].flatten.forall(_.parentScope == null), "probe leaves were not exactly consumed")
        inspect(this, probe)
        val resultFlag = out Bool()
        val resultPayload = out(Vec(Bits(4 bits), depth))
        resultFlag := reduced.flag
        resultPayload := reduced.payload
      }
    }
  }

  private def rejected(action: (Component, Vec[Bits]) => Unit): Unit = {
    val failure = intercept[Exception](generate(action))
    val messages = Iterator.iterate(failure: Throwable)(_.getCause).takeWhile(_ != null)
      .map(value => Option(value.getMessage).getOrElse("")).mkString("\n")
    assert(messages.contains("CONSUMED-PROBE-CHANGED"), messages)
  }

  test("consumed probes retain native clone metadata without copying removal authority") {
    generate { (owner, probe) =>
      val shape = ParameterizedVec.shapeOf(probe).get
      val copied = cloneOf(probe)
      assert(ParameterizedVec.shapeOf(copied).get.depth eq shape.depth)
      assert(!TypedBalancedReductionBackend.ownsConsumedProbe(copied))
      // Copying even the private receipt record cannot transfer its original
      // Vec identity. Reflection is adversarial test setup, never issuance.
      val storage = owner.userCache.values.collectFirst {
        case value: AnyRef if value.getClass.getName.endsWith("TypedBalancedReductionBackend$Storage") => value
      }.get
      val field = storage.getClass.getDeclaredFields.find(_.getName == "consumedProbeVectors").get
      field.setAccessible(true)
      val receipts = field.get(storage).asInstanceOf[java.util.IdentityHashMap[Vec[_], AnyRef]]
      receipts.put(copied, receipts.get(probe))
      try {
        val failure = intercept[IllegalArgumentException](TypedBalancedReductionBackend.ownsConsumedProbe(copied))
        assert(failure.getMessage.contains("CONSUMED-PROBE-CHANGED"), failure.getMessage)
      } finally receipts.remove(copied)
      assert(TypedBalancedReductionBackend.ownsConsumedProbe(probe))
      copied.asInstanceOf[Data].flatten.foreach(_.removeStatement())
    }
  }

  test("consumed probe receipts freeze the native clone factory identity") {
    rejected { (_, probe) =>
      probe._dataType = HardType(Bits(4 bits))
      TypedBalancedReductionBackend.ownsConsumedProbe(probe)
    }
  }

  test("consumed probe receipts reject new exact native operation evidence") {
    rejected { (_, probe) =>
      probe(0)
      TypedBalancedReductionBackend.ownsConsumedProbe(probe)
    }
  }

  test("consumed probe receipts reject resurrection of an exact removed carrier") {
    rejected { (owner, probe) =>
      owner.dslBody.append(probe.vec.head)
      TypedBalancedReductionBackend.ownsConsumedProbe(probe)
    }
  }

  test("consumed probe receipts reject a direct scalar driver without a Vec operation") {
    rejected { (_, probe) =>
      probe.vec.head := B(0, 4 bits)
      TypedBalancedReductionBackend.ownsConsumedProbe(probe)
    }
  }

  test("a direct live read cannot publish a removed native probe carrier") {
    val failure = intercept[Exception] {
      generate { (_, probe) =>
        val leaked = out(Bits(4 bits)).setName("leaked_probe")
        leaked := probe.vec.head
      }
    }
    val messages = Iterator.iterate(failure: Throwable)(_.getCause).takeWhile(_ != null)
      .map(value => Option(value.getMessage).getOrElse("")).mkString("\n")
    assert(messages.contains("OLD NETLIST RE-USED / DANGLING REFERENCE") &&
      messages.contains("leaked_probe"), messages)
  }

}

package spinal.core.internals

import java.nio.charset.StandardCharsets
import java.nio.file.{Files, Path, Paths}
import morphhdl.{MorphNamedFieldVectors, MorphSignedCasts, MorphSignedDeclarations, MorphVerilog}
import morphhdl.frontend.HdlInt
import nativeapplication.BalancedCombinedNativeOracle
import spinal.core._

/** Exercise the real generated-child formal bindings against the independent
  * native oracle, over the complete existing combined-record matrix.
  */
object TypedBalancedReductionGeneratedChildArtifactWriter {
  private val matrix = TypedBalancedReductionCombinedArtifactWriter
  private def quote(value: String): String =
    "\"" + value.replace("\\", "\\\\").replace("\"", "\\\"") + "\""
  private def relative(root: Path, file: Path): String =
    root.relativize(file).toString.replace('\\', '/')

  def main(args: Array[String]): Unit = {
    require(args.length == 1, "usage: TypedBalancedReductionGeneratedChildArtifactWriter OUTPUT")
    val root = Paths.get(args(0)).toAbsolutePath.normalize()
    Files.createDirectories(root)
    val candidates = for (layout <- matrix.layouts; signed <- matrix.signedModes;
        default <- matrix.defaults) yield {
      val suffix = layout + "_" + signed + "_d" + default
      val top = "BalancedCombinedGeneratedChildTop_" + suffix
      val child = "BalancedCombinedGeneratedChild_" + suffix
      val directory = root.resolve(s"candidate/$layout-$signed-n$default")
      val base = matrix.config(directory, top + ".v")
      val shaped = if (layout == "fields") MorphNamedFieldVectors.enable(base) else base
      val configured = signed match {
        case "legacy" => MorphSignedDeclarations.disable(MorphSignedCasts.disable(shaped))
        case "declarations" => MorphSignedDeclarations.enable(shaped)
        case "casts" => MorphSignedCasts.enable(shaped)
      }
      MorphVerilog(configured) {
        new BalancedCombinedGeneratedChildTop(HdlInt.param("WIDTH", 5, 1, 32),
          HdlInt.param("TAG_WIDTH", 3, 1, 32), HdlInt.param("COORD_WIDTH", 7, 1, 32),
          HdlInt.param("COUNT", default, 1, 17), HdlInt.param("MODE", 0, 0, 1), top, child)
      }
      val file = directory.resolve(top + ".v")
      require(Files.isRegularFile(file), "generated-child candidate was not emitted")
      s"""{"layout":${quote(layout)},"signed_mode":${quote(signed)},"default_count":$default,"module":${quote(top)},"file":${quote(relative(root, file))}}"""
    }
    val shapes = ((for (width <- matrix.widths; count <- matrix.counts; mode <- 0 to 1)
      yield (width, width, width, count, mode)) ++
      (for ((width, tag, coord) <- Vector((1, 3, 7), (5, 1, 8), (8, 32, 1), (32, 5, 7));
            count <- Vector(1, 3, 5, 17); mode <- 0 to 1)
        yield (width, tag, coord, count, mode))).distinct
    val cases = shapes.map { case (width, tag, coord, count, mode) =>
      val id = s"w${width}_t${tag}_c${coord}_n${count}_m$mode"
      val name = "NativeCombined_" + id
      val directory = root.resolve("native/" + id)
      SpinalVerilog(matrix.config(directory, name + ".v")) {
        new BalancedCombinedNativeOracle(width, tag, coord, count, mode, name)
      }
      val file = directory.resolve(name + ".v")
      require(Files.isRegularFile(file), "independent native reference was not emitted")
      s"""{"id":${quote(id)},"width":$width,"tag_width":$tag,"coord_width":$coord,"count":$count,"mode":$mode,"module":${quote(name)},"file":${quote(relative(root, file))}}"""
    }
    val manifest = s"""{"schema":1,"scope":"59i-generated-child-record-join","candidates":[${candidates.mkString(",")}],"cases":[${cases.mkString(",")}]}
"""
    Files.write(root.resolve("manifest.json"), manifest.getBytes(StandardCharsets.UTF_8))
  }
}

val child = {
  // Bind every child formal through the existing typed constructor. MODE's
  // positive encoding preserves the logical 0/1 control in the child while
  // retaining the actual parent expression, including its +1 operation.
  val concreteInputs: Boolean = Vector(width, tagWidth, coordWidth, count, mode).forall(_.asElabInt.isConcrete)
  // This dispatch is a host construction decision; only one child exists.
  concreteInputs match {
    case true => new BalancedCombinedScopedRecords(width, tagWidth, coordWidth, count, mode, childName)
    case false => ElabFormalComponent.parameters(Vector(
      ElabFormalComponent.Parameter(width.asElabInt, "WIDTH", 1, 32),
      ElabFormalComponent.Parameter(tagWidth.asElabInt, "TAG_WIDTH", 1, 32),
      ElabFormalComponent.Parameter(coordWidth.asElabInt, "COORD_WIDTH", 1, 32),
      ElabFormalComponent.Parameter(count.asElabInt, "COUNT", 1, 17),
      ElabFormalComponent.Parameter(mode.asElabInt + 1, "MODE", 1, 2))) { formals =>
      new BalancedCombinedScopedRecords(
        HdlInt.fromElabIntParameter(formals(0)),
        HdlInt.fromElabIntParameter(formals(1)),
        HdlInt.fromElabIntParameter(formals(2)),
        HdlInt.fromElabIntParameter(formals(3)),
        HdlInt.fromElabIntParameter(formals(4)) - HdlInt.literal(1), childName)
    }
  }
}.setName("child")

package spinal.core.internals

import java.nio.file.Files
import morphhdl.frontend.HdlInt
import org.scalatest.funsuite.AnyFunSuite
import spinal.core._
import spinal.lib._

/** Exercise geometry on the actual native +| graph, including exact-node
  * mutations. No generated-RTL mutation coverage is implied by this suite.
  */
class TypedBalancedReductionNativeGeometryTests extends AnyFunSuite {
  private def elaborate(body: => Unit): Unit =
    SpinalConfig(targetDirectory = Files.createTempDirectory("native-geometry-").toString,
      headerWithDate = false, headerWithRepoHash = false).generateVerilog(new Component {
      body
      val keep = out Bool()
      keep := False
    })

  private def capture(operation: (UInt, UInt) => UInt = (a: UInt, b: UInt) => a +| b)
      : (UnvalidatedBalancedCallback, TypedBalancedReductionScalarGraphReplay.Proof) = {
    val width = HdlInt.param("WIDTH", 5, 1, 9)
    val values = Vec(UInt(width bits), HdlInt.param("COUNT", 2, 2, 2))
    values.foreach(_ := 0)
    val native: ElabBalancedReduction.Native[UInt] = (elements, operation, bridge) =>
      new TraversableOnceAnyPimped[UInt](elements).reduceBalancedTree(operation, bridge)
    val callback = TypedBalancedReductionCapture(values, operation,
      (value: UInt, _: Int) => value, native).rows.head.operator.get
    val evidence = callback.operands.map(value =>
      TypedBalancedReductionValueEvidence.input(value.asInstanceOf[BaseType]))
    val proof = TypedBalancedReductionScalarGraphReplay.certify(callback, evidence)
    (callback, proof)
  }

  private def ranges(callback: UnvalidatedBalancedCallback): Vector[BitVectorRangedAccessFixed] =
    callback.assignments.map(_.source).collect { case value: BitVectorRangedAccessFixed => value }

  private def fills(callback: UnvalidatedBalancedCallback): Vector[BitVectorLiteral] =
    callback.assignments.map(_.source).collect {
      case value: BitVectorLiteral if NativeWidthProvenance.fillOf(value).nonEmpty => value
    }

  private def stale(proof: TypedBalancedReductionScalarGraphReplay.Proof): Unit = {
    val error = intercept[IllegalArgumentException](proof.validateFreshness())
    assert(error.getMessage.contains("STALE"), error.getMessage)
  }

  private def withChangedWidthAtSingleton(source: BitVector)(body: => Unit): Unit = {
    val original = NativeWidthProvenance.widthOf(source).get
    val replacement = ElaborationWidthAuthority.subtract(
      ElabInt.literal((2 * original.default).toInt).expression, original)
    assert(original.default == replacement.default)
    assert(original.minimum == replacement.minimum && original.maximum == replacement.maximum)
    assert(!ElaborationWidthAuthority.equivalent(original, replacement))
    // Exercise a changed exact native object without weakening normal public
    // attachment's provenance-conflict guard. This helper is reserved for the
    // native mux clone construction path in production.
    ParameterizedWidth.retainNativeMuxWidth(source, Some(replacement))
    try {
      val root = original.completedParameterRoots.head
      val default = original.parameters.head.default
      ElaborationDomainContext.withAdmitted(root, Set(default), None) {
        assert(ElaborationWidthAuthority.equivalent(original, replacement))
        body
      }
    } finally ParameterizedWidth.retainNativeMuxWidth(source, Some(original))
  }

  test("native saturation retains its independent source-relative slice and fill domains") {
    elaborate {
      val (callback, proof) = capture()
      val width = ParameterizedWidth.expressionOf(callback.operands.head.asInstanceOf[BaseType]).get
      assert(ElaborationWidthAuthority.equivalent(proof.resultWidth, width))
      val selected = ranges(callback)
      assert(selected.size == 2)
      selected.foreach { access =>
        val geometry = NativeWidthProvenance.rangeOf(access).get
        val sourceWidth = NativeWidthProvenance.widthOf(access.source).get
        assert(geometry.validFor(sourceWidth))
        assert(geometry.high(sourceWidth).default == access.hi)
        assert(geometry.low(sourceWidth).default == access.lo)
      }
      val literal = fills(callback).head
      val fill = NativeWidthProvenance.fillOf(literal).get
      assert(fill.source.nonEmpty)
      assert(NativeWidthProvenance.fillWidthOf(literal).get eq fill.width)
      assert(ElaborationWidthAuthority.equivalent(fill.width, width))
      val other = HdlInt.param("OTHER_WIDTH", 5, 1, 9).bits.expression.get
      assert(width.default == other.default)
      assert(!ElaborationWidthAuthority.equivalent(width, other))
      val widenedOther = ElaborationWidthAuthority.add(other, ElabInt.literal(2).expression)
      val replayWidth = proof.resultWidthFor(widenedOther, widenedOther)
      assert(ElaborationWidthAuthority.equivalent(replayWidth, widenedOther))
      assert(!ElaborationWidthAuthority.equivalent(replayWidth, width))
      proof.validateFreshness()
    }
  }

  test("actual native saturation range mutations invalidate query and scalar freshness") {
    elaborate {
      val (callback, proof) = capture()
      ranges(callback).foreach { access =>
        val original = NativeWidthProvenance.rangeOf(access).get
        val hi = access.hi
        val lo = access.lo
        access.hi = hi + 1
        try { assert(NativeWidthProvenance.rangeOf(access).isEmpty); stale(proof) }
        finally access.hi = hi
        assert(NativeWidthProvenance.rangeOf(access).contains(original))
        proof.validateFreshness()
        access.lo = lo + 1
        try { assert(NativeWidthProvenance.rangeOf(access).isEmpty); stale(proof) }
        finally access.lo = lo
        proof.validateFreshness()
      }
    }
  }

  test("same-default independent source replacement cannot inherit native range geometry") {
    elaborate {
      val (callback, proof) = capture()
      val other = UInt(HdlInt.param("OTHER_WIDTH", 5, 1, 9) bits)
      other := 0
      val replacement = other +^ other
      val access = ranges(callback).head
      val source = access.source
      assert(replacement.getBitsWidth == source.getWidth)
      access.source = replacement
      try { assert(NativeWidthProvenance.rangeOf(access).isEmpty); stale(proof) }
      finally access.source = source
      assert(NativeWidthProvenance.rangeOf(access).nonEmpty)
      proof.validateFreshness()
    }
  }

  test("range freshness rejects a changed full width function even on an equal singleton") {
    elaborate {
      val (callback, proof) = capture()
      val access = ranges(callback).head
      val geometry = NativeWidthProvenance.rangeOf(access).get
      withChangedWidthAtSingleton(access.source.asInstanceOf[BitVector]) {
        assert(NativeWidthProvenance.rangeOf(access).isEmpty)
        stale(proof)
      }
      assert(NativeWidthProvenance.rangeOf(access).contains(geometry))
      proof.validateFreshness()
    }
  }

  test("fill freshness rejects a changed full source function even on an equal singleton") {
    elaborate {
      val (callback, proof) = capture()
      val literal = fills(callback).head
      val geometry = NativeWidthProvenance.fillOf(literal).get
      withChangedWidthAtSingleton(geometry.source.get) {
        assert(NativeWidthProvenance.fillOf(literal).isEmpty)
        stale(proof)
      }
      assert(NativeWidthProvenance.fillOf(literal).contains(geometry))
      proof.validateFreshness()
    }
  }

  test("fresh all-ones construction does not inherit a stale source-relative width record") {
    elaborate {
      val source = UInt(HdlInt.param("WIDTH", 5, 2, 8) bits)
      source := 0
      val target = NativeWidthProvenance.retainRelativeWidth(source, UInt(4 bits), -1)
      val originalWidth = NativeWidthProvenance.widthOf(target).get
      withChangedWidthAtSingleton(source) {
        target.setAll()
        val assigned = target.head.source.asInstanceOf[UInt]
        val literal = assigned.head.source.asInstanceOf[UIntLiteral]
        val geometry = NativeWidthProvenance.fillOf(literal).get
        assert(geometry.source.isEmpty)
        assert(ElabInt.equivalentExpression(geometry.width, originalWidth))
      }
    }
  }

  test("actual all-ones value and width mutations invalidate exact literal provenance") {
    elaborate {
      val (callback, proof) = capture()
      val literal = fills(callback).head
      val original = NativeWidthProvenance.fillOf(literal).get
      val value = literal.value
      literal.value = value ^ 1
      try { assert(NativeWidthProvenance.fillOf(literal).isEmpty); stale(proof) }
      finally literal.value = value
      assert(NativeWidthProvenance.fillOf(literal).contains(original))
      proof.validateFreshness()
      val bits = literal.bitCount
      literal.bitCount = bits + 1
      try { assert(NativeWidthProvenance.fillOf(literal).isEmpty); stale(proof) }
      finally literal.bitCount = bits
      proof.validateFreshness()
    }
  }

  test("independent equal-default width conflicts remain rejected on native saturation operands") {
    elaborate {
      val (callback, proof) = capture()
      val operand = callback.operands.head.asInstanceOf[UInt]
      val before = ParameterizedWidth.expressionOf(operand).get
      val other = HdlInt.param("OTHER_WIDTH", 5, 1, 9)
      assert(before.default == other.bits.expression.get.default)
      val error = intercept[Exception](ParameterizedWidth.attach(operand, other.bits))
      assert(error.getMessage.contains("WIDTH-PROVENANCE-CONFLICT"), error.getMessage)
      assert(ParameterizedWidth.expressionOf(operand).get eq before)
      proof.validateFreshness()
    }
  }

  test("ordinary native zero-width setAll keeps its original concrete behavior") {
    elaborate {
      val zero = UInt(0 bits)
      val result = zero.setAll()
      assert(result eq zero)
      assert(zero.getBitsWidth == 0)
      val assigned = zero.head.source.asInstanceOf[UInt]
      val literal = assigned.head.source.asInstanceOf[UIntLiteral]
      assert(literal.value == 0)
      assert(NativeWidthProvenance.fillOf(literal).isEmpty)
    }
  }

  test("ordinary native saturation preserves a legal witness without certifying an invalid symbolic domain") {
    elaborate {
      val input = UInt(HdlInt.param("WIDTH", 5, 1, 9) bits)
      input := 0
      val result = input.sat(2)
      assert(result.getBitsWidth == 3)
      assert(ParameterizedWidth.expressionOf(result).isEmpty)
    }
  }

  test("ordinary witness acceptance does not certify saturation outside the full symbolic domain") {
    elaborate {
      val error = intercept[IllegalArgumentException](capture((a: UInt, _: UInt) => a.sat(2)))
      assert(error.getMessage.contains("SELECT-DOMAIN"), error.getMessage)
    }
  }
}

package spinal.core.internals

import java.nio.file.Files
import morphhdl.frontend.HdlInt
import org.scalatest.funsuite.AnyFunSuite
import spinal.core._

final case class BalancedFreshNestedCloneRecord(width: HdlInt, payloadWidth: HdlInt,
    depth: HdlInt) extends Bundle {
  val value = UInt(width bits)
  val payload = Vec(Vec(Bits(payloadWidth bits), depth), 2)
}

class TypedBalancedReductionNestedCloneShapeTests extends AnyFunSuite {
  private def elaborate(body: => Unit): Unit =
    SpinalConfig(targetDirectory = Files.createTempDirectory("nested-clone-shape-").toString,
      headerWithDate = false, headerWithRepoHash = false).generateVerilog(new Component {
      body
      val keep = out Bool()
      keep := False
    })

  private def source(): BalancedFreshNestedCloneRecord = {
    val result = BalancedFreshNestedCloneRecord(HdlInt.param("WIDTH", 3, 2, 5),
      HdlInt.param("PAYLOAD_WIDTH", 4, 1, 7), HdlInt.param("INNER", 2, 1, 3))
    result.value := 0
    result.payload.vec.foreach(_.vec.foreach(_ := 0))
    result
  }

  private def doubled(value: BaseType): ElaborationIntegerExpression = {
    val width = ParameterizedWidth.expressionOf(value).get
    ElaborationWidthAuthority.add(width, width)
  }

  test("nested widening clones retain independent widths and exact logical Vec depths through native cloning") {
    elaborate {
      val original = source()
      val outer = ParameterizedVec.shapeOf(original.payload).get
      val inner = ParameterizedVec.shapeOf(original.payload.vec.head).get
      val widths = original.flatten.toVector.map(doubled)
      val widened = TypedBalancedReductionCompositeReplay.cloneShape(original, widths)
        .asInstanceOf[BalancedFreshNestedCloneRecord]
      val widenedOuter = ParameterizedVec.shapeOf(widened.payload).get
      val widenedInner = ParameterizedVec.shapeOf(widened.payload.vec.head).get
      assert(widenedOuter.depth eq outer.depth)
      assert(widenedInner.depth eq inner.depth)
      assert(widenedInner.witnessDepth == 2 && widenedInner.carrierCapacity == 3)
      assert(widenedOuter.carrierCapacity == 2)
      assert(ElabInt.equivalentExpression(widenedInner.elementLeaves.head.width, widths(1)))
      assert(widenedOuter.logicalElementWidthDefault == 16)
      assert(widenedOuter.logicalElementWidthMaximum == 42)
      assert(ParameterizedVec.shapeOf(original.payload).contains(outer))
      assert(ParameterizedVec.shapeOf(original.payload.vec.head).contains(inner))
      assert(original.value.getBitsWidth == 3 && original.payload.vec.head.vec.head.getBitsWidth == 4)
      val cloned = cloneOf(widened)
      val hardTyped = HardType(widened)()
      val vectorClone = cloneOf(widened.payload)
      for (again <- Vector(cloned, hardTyped)) {
        assert(again.flatten.map(_.getBitsWidth) == widened.flatten.map(_.getBitsWidth))
        assert(ParameterizedVec.shapeOf(again.payload.vec.head).get.depth eq inner.depth)
        assert(ElabInt.equivalentExpression(
          ParameterizedVec.shapeOf(again.payload.vec.head).get.elementLeaves.head.width, widths(1)))
      }
      assert(ParameterizedVec.shapeOf(vectorClone).get.elementLayout.width(_.verilog) ==
        widenedOuter.elementLayout.width(_.verilog))
    }
  }

  test("fresh clone width substitution rejects caller-owned drivers and independent equal-default depth roots") {
    elaborate {
      val original = source()
      val assigned = cloneOf(original)
      assigned := original
      val before = ParameterizedVec.shapeOf(assigned.payload).get
      val driven = intercept[ParameterizedVerilogException] {
        ParameterizedVec.withFreshCloneWidths(original, assigned) { () }
      }
      assert(driven.code == "SPINAL-ELAB-VEC-FRESH-CLONE-SHAPE")
      assert(ParameterizedVec.shapeOf(assigned.payload).contains(before))
      val foreign = BalancedFreshNestedCloneRecord(original.width, original.payloadWidth,
        HdlInt.param("OTHER_INNER", 2, 1, 3))
      val foreignBefore = ParameterizedVec.shapeOf(foreign.payload.vec.head).get
      val root = intercept[ParameterizedVerilogException] {
        ParameterizedVec.withFreshCloneWidths(original, foreign) { () }
      }
      assert(root.code == "SPINAL-ELAB-VEC-FRESH-CLONE-SHAPE")
      assert(ParameterizedVec.shapeOf(foreign.payload.vec.head).contains(foreignBefore))
    }
  }

  test("failed nonuniform nested width substitution restores every fresh clone width and shape") {
    elaborate {
      val original = source()
      val target = cloneOf(original)
      val beforeOuter = ParameterizedVec.shapeOf(target.payload).get
      val beforeInner = ParameterizedVec.shapeOf(target.payload.vec.head).get
      val leaf = target.payload.vec.head.vec.head
      val beforeWidth = ParameterizedWidth.expressionOf(leaf).get
      val beforeFixed = leaf.fixedWidth
      val beforeObserved = leaf.widthWhenNotInferred
      val beforeInferred = leaf.inferredWidth
      val changed = doubled(leaf)
      val root = beforeWidth.completedParameterRoots.head
      val error = ElaborationDomainContext.withAdmitted(root, Set(beforeWidth.parameters.head.default), None) {
        val rejected = intercept[ParameterizedVerilogException] {
          ParameterizedVec.withFreshCloneWidths(original, target) {
            leaf.setWidth(changed.default.toInt)
            ParameterizedWidth.retainNativeMuxWidth(leaf, Some(changed))
          }
        }
        assert(ParameterizedWidth.expressionOf(leaf).get eq beforeWidth)
        assert(leaf.fixedWidth == beforeFixed)
        assert(leaf.widthWhenNotInferred == beforeObserved)
        assert(leaf.inferredWidth == beforeInferred)
        rejected
      }
      assert(error.code.contains("LAYOUT-MISMATCH"), error.getMessage)
      assert(ParameterizedVec.shapeOf(target.payload).contains(beforeOuter))
      assert(ParameterizedVec.shapeOf(target.payload.vec.head).contains(beforeInner))
      assert(leaf.getBitsWidth == 4)
      assert(ParameterizedWidth.expressionOf(leaf).contains(beforeWidth))
      assert(cloneOf(target).flatten.map(_.getBitsWidth) == original.flatten.map(_.getBitsWidth))
    }
  }

  test("recursive layout substitution preserves independent sibling dimensions and rejects same-witness root misbinding") {
    elaborate {
      val leftDepth = HdlInt.param("LEFT_INNER", 2, 1, 3).bits.expression.get
      val rightDepth = HdlInt.param("RIGHT_INNER", 2, 1, 3).bits.expression.get
      val leftWidth = HdlInt.param("LEFT_WIDTH", 4, 2, 6).bits.expression.get
      val rightWidth = HdlInt.param("RIGHT_WIDTH", 4, 2, 6).bits.expression.get
      import ParameterizedVecElementLayout._
      val layout = Layout(Fields(classOf[BalancedFreshNestedCloneRecord], Vector(
        "left" -> Dimension(leftDepth, 3, Scalar(TypeBits, leftWidth)),
        "right" -> Dimension(rightDepth, 3, Scalar(TypeBits, rightWidth)))))
      val wideLeft = ElaborationWidthAuthority.add(leftWidth, leftWidth)
      val wideRight = ElaborationWidthAuthority.add(rightWidth, rightWidth)
      val substituted = Vector.fill(3)(wideLeft) ++ Vector.fill(3)(wideRight)
      val changed = layout.withLeafWidths(substituted)
      assert(wideLeft.default == wideRight.default)
      assert(!ElaborationWidthAuthority.equivalent(wideLeft, wideRight))
      assert(changed.leaves.take(3).forall(_.dimensions.head._2 eq leftDepth))
      assert(changed.leaves.drop(3).forall(_.dimensions.head._2 eq rightDepth))
      assert(changed.leaves.map(_.dimensions.head._1) == Vector(0, 1, 2, 0, 1, 2))
      assert(changed.width(_.verilog).contains("LEFT_INNER"))
      assert(changed.width(_.verilog).contains("RIGHT_INNER"))
      val mismatched = intercept[ParameterizedVerilogException] {
        layout.withLeafWidths(substituted.updated(1, wideRight))
      }
      assert(mismatched.code == "SPINAL-ELAB-VEC-LAYOUT-WIDTH-SUBSTITUTION")
      intercept[ParameterizedVerilogException] {
        layout.withLeafWidths(substituted.updated(0, wideLeft.copy()))
      }
      assert(layout.leaves.head.width eq leftWidth)
      assert(layout.leaves.last.width eq rightWidth)
    }
  }
}

